#!/usr/bin/env python3
"""Render every generated file in this repo from two inputs:

  mcp.config.json       URLs, names, contacts (edit this)
  catalog/catalog.json  tools/prompts/resources, generated from the server code
                        (`make sync` in the private gupshup-mcp-server repo)

Outputs (do not edit by hand, they are overwritten):
  README.md sections between <!-- BEGIN:x --> / <!-- END:x --> markers
  docs/reference/{analytics,templates,campaigns}.md, docs/prompts.md
  docs/clients/*.md, docs/self-serve.md
  server.json, .claude-plugin/marketplace.json,
  plugins/gupshup-mcp/.claude-plugin/plugin.json, plugins/gupshup-mcp/.mcp.json,
  plugins/gupshup-mcp/.cursor-plugin/plugin.json, plugins/gupshup-mcp/mcp.json, .cursor-plugin/marketplace.json

Stdlib only.  Usage: python3 scripts/render_docs.py [--check]
--check exits 1 if any output would change (CI drift guard).
"""

from __future__ import annotations

import argparse
import base64
import json
import re
import sys
import urllib.parse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CFG = json.loads((ROOT / "mcp.config.json").read_text())
CATALOG = json.loads((ROOT / "catalog" / "catalog.json").read_text())

URL = CFG["mcp_url_legacy"] if CFG["use_legacy_as_primary"] else CFG["mcp_url"]
NAME = CFG["server_name"]
RISK = {"read": "Read-only", "write": "Writes", "sends": "**Sends messages**", "destructive": "**Deletes data**"}
APP_BY_KEY = {a["key"]: a for a in CATALOG["apps"]}
GENERATED = "<!-- Generated by scripts/render_docs.py from catalog/catalog.json. Do not edit by hand. -->\n"

outputs: dict[Path, str] = {}


def emit(rel: str, content: str) -> None:
    outputs[ROOT / rel] = content if content.endswith("\n") else content + "\n"


def emit_json(rel: str, data: object) -> None:
    emit(rel, json.dumps(data, indent=2, ensure_ascii=False))


def md_escape(text: str) -> str:
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


# ---------- install links ----------
# GitHub strips cursor:// and vscode: links from rendered Markdown, so buttons use
# the vendors' https redirect pages, which hand off to the installed app.
CURSOR_BADGE = "https://cursor.com/deeplink/mcp-install-dark.svg"
VSCODE_BADGE = "https://img.shields.io/badge/VS_Code-Install_Gupshup-0098FF?style=for-the-badge"
CLAUDE_BADGE = "https://img.shields.io/badge/Claude-Add_Gupshup-D97757?style=for-the-badge&logo=claude&logoColor=white"
VSCODE_INS_BADGE = "https://img.shields.io/badge/VS_Code_Insiders-Install_Gupshup-24bfa5?style=for-the-badge"


def cursor_config(url: str, headers: dict | None = None) -> str:
    cfg = {"url": url, **({"headers": headers} if headers else {})}
    return urllib.parse.quote(base64.b64encode(json.dumps(cfg, separators=(",", ":")).encode()).decode(), safe="")


def cursor_link(name: str = NAME, url: str = URL, headers: dict | None = None) -> str:
    """Native deeplink (for the website / copy-paste)."""
    return f"cursor://anysphere.cursor-deeplink/mcp/install?name={name}&config={cursor_config(url, headers)}"


def cursor_https(name: str = NAME, url: str = URL, headers: dict | None = None) -> str:
    """https page on cursor.com that opens Cursor's install dialog: works from GitHub."""
    return f"https://cursor.com/install-mcp?name={name}&config={cursor_config(url, headers)}"


def vscode_link(insiders: bool = False) -> str:
    cfg = urllib.parse.quote(json.dumps({"type": "http", "url": URL}, separators=(",", ":")), safe="")
    host = "insiders.vscode.dev" if insiders else "vscode.dev"
    return f"https://{host}/redirect/mcp/install?name={NAME}&config={cfg}" + ("&quality=insiders" if insiders else "")


def claude_link(admin: bool = False) -> str:
    """Official prefill link: opens Claude's Add-custom-connector dialog with name + URL filled in."""
    base = "https://claude.ai/admin-settings/connectors" if admin else "https://claude.ai/customize/connectors"
    return (f"{base}?modal=add-custom-connector&connectorName=Gupshup"
            f"&connectorUrl={urllib.parse.quote(URL, safe='')}")


def install_buttons() -> str:
    return (f"[![Add to Claude]({CLAUDE_BADGE})]({claude_link()}) "
            f"[![Add to Cursor]({CURSOR_BADGE})]({cursor_https()}) "
            f"[![Install in VS Code]({VSCODE_BADGE})]({vscode_link()}) "
            f"[![Install in VS Code Insiders]({VSCODE_INS_BADGE})]({vscode_link(insiders=True)})")


# ---------- reference docs ----------
def schema_type(p: dict) -> str:
    if "enum" in p:
        return " \\| ".join(f"`{json.dumps(v)}`" for v in p["enum"])
    if "anyOf" in p:
        parts = [schema_type(x) for x in p["anyOf"] if x.get("type") != "null"]
        return " \\| ".join(parts) or "any"
    if p.get("type") == "array":
        return f"{schema_type(p.get('items', {}))}[]"
    if "$ref" in p:
        return p["$ref"].rsplit("/", 1)[-1]
    return f"`{p.get('type', 'object')}`"


def params_table(schema: dict | None) -> str:
    props = (schema or {}).get("properties") or {}
    if not props:
        return "_No parameters._\n"
    required = set((schema or {}).get("required") or [])
    with_desc = any((p.get("description") or "").strip() for p in props.values())
    head = "| Parameter | Type |" + (" Description |" if with_desc else "") + "\n"
    head += "|---|---|" + ("---|" if with_desc else "") + "\n"
    rows = []
    for name, p in props.items():
        req = " **(required)**" if name in required else ""
        row = f"| `{name}`{req} | {schema_type(p)} |"
        if with_desc:
            row += f" {md_escape(p.get('description', ''))} |"
        rows.append(row)
    return head + "\n".join(rows) + "\n"


def render_reference() -> None:
    for app in CATALOG["apps"]:
        tools = [t for t in CATALOG["tools"] if t["app"] == app["key"]]
        callable_ = [t for t in tools if not t["app_only"]]
        panel = [t for t in tools if t["app_only"]]
        out = [GENERATED, f"# {app['label']} tools\n",
               f"{app['summary']}\n",
               f"**OAuth scope:** {', '.join(f'`{s}`' for s in app['scopes'])} · "
               f"**Tools:** {len(callable_)} callable" + (f" + {len(panel)} review-panel actions" if panel else "") +
               f" · **Approx. context cost:** ~{round(app['approx_tool_tokens'] / 100) / 10}k tokens\n",
               "| Tool | What it does | Action |\n|---|---|---|"]
        out += [f"| [`{t['name']}`](#{t['name']}) | {md_escape(t['summary'])} | {RISK[t['risk']]} |" for t in callable_]
        out.append("")
        for t in callable_:
            out += [f"## `{t['name']}`\n", f"{t['summary']}\n"]
            meta = [f"**Action:** {RISK[t['risk']]}"]
            if t["channels"]:
                meta.append("**Channels:** " + ", ".join(t["channels"]))
            if t["ui_resource"]:
                meta.append(f"**Opens panel:** `{t['ui_resource']}`")
            out += [" · ".join(meta) + "\n", params_table(t["input_schema"])]
            out += ["<details><summary>Model-facing description</summary>\n", f"{t['description']}\n", "</details>\n"]
        if panel:
            out += ["## Review-panel actions\n",
                    "These tools are called by the interactive review panel (MCP Apps) when you click in it. "
                    "They are not offered to the model, and clients that don't render panels never call them.\n",
                    "| Tool | Panel | Purpose |\n|---|---|---|"]
            out += [f"| `{t['name']}` | `{t['ui_resource']}` | {md_escape(t['summary'])} |" for t in panel]
            out.append("")
        emit(f"docs/reference/{app['key']}.md", "\n".join(out))


def render_prompts() -> None:
    out = [GENERATED, "# Prompts\n",
           "Prompts are ready-made starting points. In clients that support MCP prompts they appear as slash commands "
           "(for example `/mcp__gupshup__draft-message-template` in Claude Code); elsewhere, paste the example as your message.\n"]
    for app in CATALOG["apps"]:
        prompts = [p for p in CATALOG["prompts"] if p["app"] == app["key"]]
        out += [f"## {app['label']}\n", "| Prompt | What it does | Try asking |\n|---|---|---|"]
        for p in prompts:
            desc = p.get("friendly_description") or p["description"]
            example = f"“{md_escape(p['example'])}”" if p.get("example") else ""
            out.append(f"| `/{p['name']}` | {md_escape(desc)} | {example} |")
        out.append("")
    out += ["## Interactive review panels\n",
            "Panels are MCP Apps (`ui://` resources) that render inside clients that support them. "
            "Clients without MCP Apps support get the same information as text, and launches still require confirmation.\n",
            "| Panel | Purpose |\n|---|---|"]
    out += [f"| `{r['uri']}` | {md_escape(r['description'])} |" for r in CATALOG["resources"]]
    emit("docs/prompts.md", "\n".join(out))


